// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address ownerEOA, address newOwner) public {
        vm.assume(ownerEOA != address(0));
        vm.assume(newOwner != address(0));
        vm.deal(ownerEOA, 1 ether);

        c.setOwner(ownerEOA);
        assertTrue(c.owner() == ownerEOA);

        vm.prank(ownerEOA);
        IntermediateForwarder f = new IntermediateForwarder();

        bool ok;
        vm.prank(address(f));
        try f.callSetOwner(address(c), newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == ownerEOA);
    }
}

contract IntermediateForwarder {
    function callSetOwner(address cAddr, address newOwner) external {
        Owned(cAddr).setOwner(newOwner);
    }
}
